import test from 'node:test';
import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
import {fixture,E,props as P,research,currentCase,sources} from './rpg-fixture.mjs';
const registered=new Set();
const traces={};let scenarioFailed=false;
function cap(id,scenario){assert.ok(!registered.has(id),'duplicate capability '+id);registered.add(id);test('capability '+String(id).padStart(3,'0')+': '+globalThis.ActionCatalog.byId[id].description,()=>{globalThis.capabilityTrace=[];try{scenario();traces[id]=globalThis.capabilityTrace;}catch(error){scenarioFailed=true;throw error;}finally{delete globalThis.capabilityTrace;}});}
const inventory=(f,label,p={},a={})=>f.item(label,p,'inventory',a);
const floor=(f,label,p={},a={})=>f.item(label,p,f.m.place,a);
const itemId=(f,e)=>f.entity(e).id;
const b=f=>f.m.world.player.body;
const r=f=>f.m.world.rpg;
const goal=f=>r(f).goals.find(g=>g.id===r(f).primaryGoalId);
const task=f=>r(f).tasks.at(-1);
const clock=f=>r(f).clock.minute;
const wait=(f,n=30)=>f.pass('Пропускаю время '+n);
function goalFixture(){const f=fixture();f.pass('Ставлю цель: заработать 10 монет');return f;}
function friendFixture(){const f=fixture(),n=f.actor();n.trust=3;f.m.trust=3;n.social.relationship.affection=3;n.social.relationship.respect=3;return f;}
function damaged(f,label='повреждённая тележка'){return floor(f,label,{material:'wood',durability:25,missingParts:[]},{ownerId:f.actor().id});}
function repairTools(f){inventory(f,'ремонтный инструмент',{material:'metal',functions:['repair','pliers']});inventory(f,'запасная доска',{material:'wood'});}
cap(1,()=>{const f=goalFixture();assert.equal(goal(f).condition.type,'earn');assert.equal(goal(f).condition.amount,10);assert.equal(goal(f).status,'active');f.m.world.player.money=10;wait(f,1);assert.equal(goal(f).status,'completed');});
cap(2,()=>{const f=goalFixture();f.pass('Добавляю подцели: добраться в город; заработать 5 монет');assert.ok(goal(f).objectives.some(o=>o.condition.type==='reach'));f.run('Выхожу','Иду в город');assert.ok(goal(f).objectives.some(o=>o.status==='completed'));assert.equal(goal(f).status,'active');});
cap(3,()=>{const f=goalFixture();f.pass('Ставлю цель: заработать 20 монет');const first=goal(f).id;f.pass('Выбираю главную цель заработать 20 монет');assert.notEqual(goal(f).id,first);assert.equal(r(f).goals.length,2);});
cap(4,()=>{const f=goalFixture();const first=goal(f).id;f.pass('Отказываюсь от основного сюжета');assert.equal(r(f).goals.find(g=>g.id===first).status,'abandoned');assert.ok(r(f).arcs.some(a=>a.source==='abandonment'));assert.equal(f.m.stage,0);});
cap(5,()=>{const f=goalFixture();const first=goal(f).id;f.pass('Меняю цель: заработать 15 монет');assert.equal(r(f).goals.find(g=>g.id===first).status,'superseded');assert.equal(r(f).goals.at(-1).predecessorId,first);});
cap(6,()=>{const f=goalFixture();f.pass('Обсуждаю способы достижения цели с Мирой');assert.ok(goal(f).alternatives.length>=2);assert.equal(f.last.messages.filter(m=>m.speaker.id===f.actor().id).length,1);});
cap(7,()=>{const f=goalFixture();f.pass('Предлагаю совместное дело Мире');const plan=r(f).plans.at(-1);assert.ok(plan.actorIds.includes(f.actor().id));assert.ok(plan.steps.length);assert.equal(goal(f).status,'active');});
cap(8,()=>{const f=goalFixture(),board=inventory(f,'доска');f.pass('Составляю личный план доска 60');const plan=r(f).plans.at(-1);assert.ok(plan.resources.includes(board.id));assert.ok(plan.deadline>clock(f));assert.equal(plan.goalId,goal(f).id);});
cap(9,()=>{const f=goalFixture();f.m.world.player.money=10;wait(f,1);f.pass('Проверяю прогресс цели');assert.ok(goal(f).history.some(h=>h.type==='progress'&&h.actionId));assert.match(f.last.text,/1\/1/);});
cap(10,()=>{const f=fixture(),e=damaged(f);f.pass('Предлагаю самостоятельно решить ремонт '+e.label);assert.equal(goal(f).condition.targetId,e.id);repairTools(f);f.pass('Ремонтирую '+e.label);assert.equal(goal(f).status,'completed');});
cap(11,()=>{const f=friendFixture(),lost=f.actor('Ника');lost.hidden=true;lost.status='missing';f.local('Илья');f.pass('Организую поиски пропавшего Ника Мира Илья');assert.equal(r(f).tasks.length,2);wait(f,120);assert.equal(f.actor('Ника').hidden,false);assert.ok(r(f).events.some(e=>e.type==='person_found'));});
cap(12,()=>{const f=goalFixture();f.m.world.player.money=5;f.pass('Объявляю награду 3');assert.equal(f.m.world.player.money,2);assert.equal(goal(f).bounty.amount,3);assert.equal(goal(f).bounty.claimed,false);});
cap(13,()=>{const f=goalFixture(),e=damaged(f);f.pass('Поручаю Мире починить '+e.label);assert.equal(task(f).goalId,goal(f).id);assert.equal(task(f).type,'repair');wait(f);assert.equal(task(f).status,'blocked');assert.equal(P(f.entity(e)).durability,25);});
cap(14,()=>{const f=goalFixture();goal(f).status='failed';const previous=goal(f).id;f.pass('Пересматриваю проваленную задачу');assert.equal(r(f).goals.at(-1).predecessorId,previous);assert.equal(r(f).arcs.at(-1).source,'failure');});
cap(15,()=>{const f=goalFixture(),canon=f.config.canon;f.pass('Начинаю собственную историю');assert.equal(r(f).arcs.at(-1).goalId,goal(f).id);f.m.world.player.money=10;wait(f,1);assert.equal(r(f).arcs.at(-1).status,'resolved');assert.equal(f.config.canon,canon);});
cap(16,()=>{const f=fixture(),chair=floor(f,'табурет',{mass:8,height:.5,functions:['seat']});f.pass('Сажусь на табурет');f.save();f.run('Осматриваюсь');assert.equal(b(f).posture,'sitting');assert.equal(b(f).seatId,chair.id);f.pass('Встаю');assert.equal(b(f).posture,'standing');});
cap(17,()=>{const f=fixture(),bed=floor(f,'кровать',{mass:30,functions:['bed']});f.pass('Ложусь на кровать');assert.equal(b(f).seatId,bed.id);f.save();assert.equal(b(f).posture,'lying');});
cap(18,()=>{const f=fixture(),cover=floor(f,'ящик',{height:1.2,width:1,position:{x:1,y:0,z:0}});f.pass('Приседаю за ящик');assert.equal(b(f).coverId,cover.id);assert.equal(b(f).posture,'crouching');assert.equal(f.m.facts.hidden,true);});
function portalFixture(height=.5,width=.7){const f=fixture(),destination=f.m.world.locations.find(l=>l.name==='улица'),e=floor(f,'низкий лаз',{height,width,portal:{from:f.m.world.player.location,to:destination.id,height,width}},{kind:'barrier',locked:false});return {f,e,destination};}
cap(19,()=>{const {f,destination}=portalFixture();f.pass('Ползу через низкий лаз');assert.equal(f.m.world.player.location,destination.id);assert.ok(r(f).events.some(e=>e.type==='passage_created'));});
cap(20,()=>{const {f,e,destination}=portalFixture(2,.3);f.run('Протискиваюсь через низкий лаз');assert.equal(f.last.results[0].code,'body_does_not_fit');P(f.entity(e)).portal.width=.6;f.pass('Протискиваюсь через низкий лаз');assert.equal(f.m.world.player.location,destination.id);});
cap(21,()=>{const f=fixture(),e=floor(f,'ограда',{height:4,mass:30});f.run('Перелезаю ограда');assert.equal(f.last.results[0].code,'too_high');P(f.entity(e)).supportedBy='real-support';f.pass('Перелезаю ограда');assert.equal(b(f).elevation,4);});
cap(22,()=>{const f=fixture(),e=floor(f,'высокий стол',{mass:30,height:2});f.pass('Забираюсь на высокий стол');assert.equal(b(f).supportId,e.id);assert.equal(b(f).elevation,2);});
cap(23,()=>{const f=fixture();b(f).elevation=4;b(f).position={x:0,y:0,z:4};f.run('Спрыгиваю');assert.ok(b(f).injuries.legs>0);assert.ok(b(f).health<10);assert.equal(b(f).elevation,0);});
cap(24,()=>{const f=fixture(),gap=floor(f,'яма',{gap:1,width:1,height:0});f.pass('Перепрыгиваю яму');assert.ok(b(f).position.x>P(f.entity(gap)).position.x+1);P(f.entity(gap)).gap=10;f.run('Перепрыгиваю яму');assert.ok(b(f).injuries.legs);});
cap(25,()=>{const f=fixture(),e=floor(f,'лестница',{height:5,functions:['climb'],anchored:true});f.pass('Лезу по лестнице');assert.equal(b(f).supportId,e.id);assert.equal(b(f).elevation,5);});
cap(26,()=>{const f=fixture();f.m.world.locations.find(l=>l.id===f.m.world.player.location).environment.depth=2;f.pass('Плыву');assert.equal(b(f).posture,'swimming');assert.ok(b(f).stamina<100);});
cap(27,()=>{const f=fixture();f.m.world.locations.find(l=>l.id===f.m.world.player.location).environment.depth=5;f.pass('Ныряю');assert.equal(b(f).depth,3);assert.equal(b(f).breath,80);});
cap(28,()=>{const f=fixture();f.m.world.locations.find(l=>l.id===f.m.world.player.location).environment.light=0;f.pass('Иду на ощупь');assert.equal(b(f).position.x,.5);assert.equal(b(f).posture,'cautious');});
cap(29,()=>{const {f,e,destination}=portalFixture();inventory(f,'тяжёлый молот',{mass:10});f.pass('Проламываю низкий лаз с помощью тяжёлого молота');assert.equal(f.entity(e).destroyed,true);assert.ok(f.m.world.edges.some(edge=>edge.to===destination.id&&edge.rpg?.breach));});
function doorFixture(){const f=fixture(),door=floor(f,'створка',{height:2},{kind:'barrier',opened:true,locked:false});inventory(f,'клин',{mass:1});return {f,door};}
cap(30,()=>{const {f,door}=doorFixture();f.pass('Удерживаю дверь створка');assert.equal(P(f.entity(door)).heldBy,'player');f.run('Закрываю створка');assert.equal(f.last.results[0].code,'door_held_open');});
cap(31,()=>{const {f,door}=doorFixture();f.pass('Подпираю дверь створка с помощью клина');assert.ok(P(f.entity(door)).wedgedBy);f.run('Закрываю створка');assert.equal(f.entity(door).opened,true);});
cap(32,()=>{const {f,door}=doorFixture();f.pass('Блокирую проход створка с помощью клина');assert.equal(P(f.entity(door)).blocked,true);assert.ok(P(f.entity(door)).blockedBy);});
cap(33,()=>{const f=fixture(),one=floor(f,'ящик',{height:1}),two=floor(f,'табурет',{height:.6});f.pass('Строю точку доступа из ящика и табурета');assert.equal(P(f.entity(one)).accessHeight,1.6);assert.equal(P(f.entity(two)).supportedBy,one.id);});
cap(34,()=>{const f=fixture(),one=floor(f,'доска',{height:1.5}),two=floor(f,'ящик');f.pass('Строю укрытие из доски и ящика');const cover=f.m.entities.find(e=>e.label==='импровизированное укрытие');assert.ok(cover);assert.deepEqual(cover.lineage.sort(),[one.id,two.id].sort());assert.equal(P(f.entity(one)).assembledInto,cover.id);});
cap(35,()=>{const f=friendFixture();f.pass('Прошу следовать за мной Миру');f.run('Выхожу','Иду в город');assert.equal(f.actor().location,f.m.world.player.location);f.save();assert.equal(f.actor().agency.companion,true);});
// Further domains below use the same public reply/restore path and state assertions.
cap(36,()=>{const f=fixture(),e=floor(f,'скрытая шкатулка',{visibility:{minHeight:3}},{hidden:true,known:false});f.pass('Осматриваю с высоты');assert.equal(f.entity(e).hidden,true);b(f).elevation=2;f.pass('Осматриваю с высоты');assert.equal(f.entity(e).hidden,false);assert.ok(f.last.outcome.information.novel);});
function trace(f,data={}){const t={id:'fixture:trace:'+r(f).traces.length,locationId:f.m.world.player.location,type:'mud',created:clock(f)-30,discovered:false,...data};r(f).traces.push(t);return t;}
cap(37,()=>{const f=fixture(),mud=trace(f),blood=trace(f,{type:'blood'});f.pass('Ищу следы крови');assert.ok(research(f).knownTraces.includes(blood.id));assert.ok(!research(f).knownTraces.includes(mud.id));});
cap(38,()=>{const f=fixture(),e=floor(f,'пустая бочка',{hollow:true,position:{x:-2,y:0,z:0}});f.pass('Простукиваю пустую бочку');f.pass('Определяю направление звука');assert.match(f.last.text,/слева/);assert.ok(Object.values(research(f).properties).some(v=>v.method==='direction'));});
cap(39,()=>{const {f,e,destination}=portalFixture();P(f.entity(e)).soundTransmission=.7;r(f).events.push({id:'heard',type:'utterance',npcId:f.actor('Илья').id,locationId:destination.id,time:clock(f),text:'Я оставил инструмент здесь.'});f.pass('Слушаю за дверью низкий лаз');assert.ok(Object.values(research(f).properties).some(v=>v.data.text==='Я оставил инструмент здесь.'));assert.equal(f.m.world.activeNpcId,null);});
cap(40,()=>{const f=fixture();f.pass('Привет');f.pass('Подслушиваю Миру');assert.ok(Object.values(research(f).properties).some(v=>v.method==='overheard'));assert.ok(!f.last.messages.some(m=>m.speaker.type==='npc'&&m.trigger==='conversation'));});
cap(41,()=>{const {f,e,destination}=portalFixture();f.entity(e).label='окно';f.actor('Ника').location=destination.id;f.pass('Подсматриваю в окно');const view=Object.values(research(f).properties).find(v=>v.method==='peek');assert.ok(view.data.people.includes(f.actor('Ника').id));assert.equal(f.m.world.player.location,P(f.entity(e)).portal.from);});
cap(42,()=>{const f=fixture(),n=f.actor(),t=trace(f,{actorId:n.id});f.pass('Ищу следы');f.pass('Изучаю перемещения Миры');assert.equal(research(f).tracking.npcId,n.id);assert.equal(research(f).tracking.last,t.locationId);});
cap(43,()=>{const f=fixture();inventory(f,'красная доска',{quality:.5});inventory(f,'синяя доска',{quality:1});f.pass('Сравниваю красную доску и синюю доску');assert.ok(Object.values(research(f).properties).some(v=>v.data.differences.includes('quality')));});
cap(44,()=>{const f=fixture(),e=inventory(f,'старая монета',{material:'metal'},{provenance:{created:100,origin:'архив'}});f.pass('Определяю происхождение старой монеты');assert.ok(Object.values(research(f).properties).some(v=>v.data.origin==='архив'&&v.data.age===440));assert.equal(P(f.entity(e)).material,'metal');});
cap(45,()=>{const f=fixture(),e=floor(f,'панель',{mechanism:{description:'узкий паз',discovered:false}});f.pass('Ищу тайный механизм в панели');assert.equal(P(f.entity(e)).mechanism.discovered,true);});
cap(46,()=>{const f=fixture(),e=inventory(f,'сосуд',{hollow:true});f.pass('Простукиваю сосуд');assert.equal(research(f).properties[e.id+':knock'].data.hollow,true);assert.ok(r(f).events.some(v=>v.type==='sound'));});
cap(47,()=>{const f=fixture(),e=floor(f,'масляная лужа');trace(f,{smell:'oil',sourceId:e.id});f.pass('Ищу источник запаха');assert.match(f.last.text,/масляная лужа/);assert.ok(research(f).knownTraces.length);});
cap(48,()=>{const f=fixture(),e=inventory(f,'табличка',{fineDetails:'секретная цифра'});f.m.world.locations.find(l=>l.id===f.m.world.player.location).environment.light=0;f.run('Исследую в темноте табличку');assert.equal(f.last.results[0].code,'limited_observation');const observation=research(f).properties[e.id+':touch'];assert.equal(observation.data.fineDetails,undefined);});
cap(49,()=>{const f=fixture(),e=inventory(f,'пластина',{fineDetails:'царапина в форме круга'});inventory(f,'лупа',{functions:['magnify']});f.pass('Изучаю под лупой пластину');assert.equal(research(f).properties[e.id+':magnified'].data,'царапина в форме круга');});
cap(50,()=>{const f=fixture();trace(f,{created:clock(f)-70});f.pass('Определяю свежесть следов');assert.match(f.last.text,/70 минут/);assert.ok(research(f).knownTraces.length);});
cap(51,()=>{const f=fixture();inventory(f,'цилиндр',{hollow:true});f.pass('Выдвигаю физическую гипотезу цилиндр полый');f.pass('Проверяю гипотезу опытом');assert.equal(r(f).experiments.at(-1).confirmed,true);assert.equal(research(f).hypotheses.at(-1).status,'supported');});
cap(52,()=>{const f=fixture(),e=inventory(f,'цилиндр',{hollow:true});f.pass('Выдвигаю физическую гипотезу цилиндр полый');f.pass('Провожу эксперимент');P(f.entity(e)).temperature=80;f.pass('Повторяю эксперимент');assert.equal(r(f).experiments.length,2);assert.notDeepEqual(r(f).experiments[0].conditions,r(f).experiments[1].conditions);});
cap(53,()=>{const f=fixture();f.pass('Систематически обследую помещение');f.run('Выхожу');f.pass('Отмечаю проверенную комнату');assert.equal(Object.keys(research(f).sweeps).length,2);f.save();assert.equal(Object.keys(research(f).sweeps).length,2);});
cap(54,()=>{const f=fixture(),paper=inventory(f,'бумага',{material:'paper'});inventory(f,'карандаш',{functions:['write']});f.run('Выхожу');f.pass('Рисую карту');const map=r(f).maps.at(-1);assert.equal(map.itemId,paper.id);assert.ok(map.locations.every(l=>f.m.world.loops.exploration.visited.includes(l.id)));assert.ok(!map.locations.some(l=>l.name==='рынок'));});
