for(const [id,command,field]of [[56,'Толкаю тележку','position'],[57,'Тяну тележку','position'],[58,'Приподнимаю край тележки','tilt']])cap(id,()=>{const f=fixture(),e=floor(f,'тележка',{mass:10});const before=structuredClone(P(e)[field]);f.pass(command);assert.notDeepEqual(P(f.entity(e))[field],before);assert.equal(f.entity(e).location,f.m.place);});
