cap(62,()=>{const f=fixture(),one=floor(f,'доска',{mass:1,width:1}),two=floor(f,'ящик',{mass:5,width:2,height:1});f.pass('Ставлю сверху доску на ящик');assert.equal(P(f.entity(one)).supportedBy,two.id);assert.equal(P(f.entity(one)).position.z,1);});
cap(63,()=>{const f=fixture(),one=floor(f,'распорка',{mass:2}),two=floor(f,'панель',{mass:5});f.pass('Подпираю распорку под панель');assert.equal(P(f.entity(two)).bracedBy,one.id);assert.equal(P(f.entity(one)).supports,two.id);});
function knotFixture(){const f=fixture(),e=inventory(f,'кулёк'),anchor=floor(f,'столб',{anchored:true,mass:100}),rope=inventory(f,'верёвка',{functions:['tie']});f.pass('Привязываю кулёк к столбу');return {f,e,anchor,rope};}
cap(64,()=>{const {f,e,anchor,rope}=knotFixture();assert.equal(P(f.entity(e)).tiedTo,anchor.id);assert.equal(r(f).links.at(-1).ropeId,rope.id);});
cap(65,()=>{const {f,e,rope}=knotFixture();f.pass('Ослабляю узел кулёк');assert.equal(r(f).links.at(-1).tension,.5);inventory(f,'нож',{functions:['cut']});f.pass('Перерезаю узел кулёк');assert.equal(r(f).links.at(-1).tied,false);assert.equal(f.entity(rope).destroyed,true);assert.equal(P(f.entity(e)).tiedTo,undefined);});
function fastenerFixture(){const f=fixture(),e=floor(f,'панель'),bolt=inventory(f,'болт',{functions:['fasten']}),tool=inventory(f,'отвёртка',{functions:['fasten','unfasten']});f.pass('Прикрепляю панель с помощью болта');return {f,e,bolt,tool};}
