cap(312,()=>{const f=guildFixture();r(f).contracts.push({id:'completed-guild-job',factionId:r(f).factions[0].id,fulfilled:true,status:'paid'});f.pass('Прошу повышение ранга Мастера');assert.equal(r(f).memberships.player[0].rank,1);assert.equal(r(f).memberships.player[0].title,'мастер');f.run('Прошу повышение ранга Мастера');assert.equal(f.last.results[0].code,'rank_not_earned');});
cap(313,()=>{const f=guildFixture();damaged(f);repairTools(f);f.pass('Беру задание организации Мастера');const contract=r(f).contracts.at(-1);assert.equal(contract.factionId,r(f).factions[0].id);f.pass('Ремонтирую повреждённую тележку');f.pass('Требую оплату услуги');f.pass('Прошу повышение ранга Мастера');assert.equal(r(f).memberships.player[0].rank,1);});
cap(314,()=>{const f=guildFixture();f.run('Оскорбляю Миру');f.pass('Разбираю нарушение правил организации Мастера');assert.equal(r(f).memberships.player[0].status,'expelled');assert.ok(r(f).factions[0].reputation.player<0);});
cap(315,()=>{const f=friendFixture();f.local('Илья');f.actor('Илья').trust=2;f.pass('Создаю объединение Мира Илья: Искатели');const faction=r(f).factions.find(g=>g.name==='Искатели');assert.ok(faction);assert.equal(faction.members.length,2);assert.equal(r(f).memberships.player[0].title,'основатель');});
cap(316,()=>{const f=guildFixture();r(f).memberships.player[0].rank=2;f.m.world.player.money=5;f.pass('Нанимаю участника организации Ника Мастера 2');assert.ok(r(f).factions[0].members.includes(f.actor('Ника').id));assert.equal(f.actor('Ника').agency.membershipEmployment.wage,2);assert.equal(f.m.world.player.money,3);});
cap(317,()=>{const f=factionFixture();for(const g of r(f).factions)g.reputation.player=2;f.pass('Налаживаю отношения организаций Мастера Торговцы');assert.equal(r(f).factions[0].relations[r(f).factions[1].id],1);assert.equal(r(f).factions[1].relations[r(f).factions[0].id],1);});
cap(318,()=>{const f=fixture();f.local('Илья');f.pass('Организую публичное мероприятие Мира Илья в город');assert.equal(r(f).agreements.at(-1).status,'planned');wait(f,40);assert.equal(r(f).agreements.at(-1).status,'held');assert.equal(r(f).agreements.at(-1).attended.length,2);});
cap(319,()=>{const f=fixture(),loc=f.m.world.locations.find(l=>l.id===f.m.world.player.location);loc.ownerId='player';f.pass('Ввожу правила помещения: visitors=false; minimumRank=1');const actual=f.m.world.locations.find(l=>l.id===f.m.world.player.location);assert.equal(actual.environment.accessRules.visitors,false);assert.ok(f.m.world.edges.filter(e=>e.to===actual.id).every(e=>e.rpg.private&&e.rpg.minimumRank===1));});
cap(320,()=>{const f=fixture(),one=inventory(f,'доска'),two=inventory(f,'кирпич',{material:'stone'});inventory(f,'молоток',{functions:['hammer']});f.pass('Строю инфраструктуру доска и кирпич');assert.equal(f.entity(one).destroyed,true);assert.equal(f.entity(two).destroyed,true);assert.equal(r(f).settlement.infrastructure,1);f.save();assert.equal(f.m.world.locations.find(l=>l.id===f.m.world.player.location).environment.infrastructure,1);});
cap(321,()=>{const f=guildFixture();for(const name of ['Мира','Илья']){f.actor(name).trust=2;f.actor(name).social.relationship.respect=2;}f.m.trust=2;f.pass('Участвую в выборах Мастера Мира Илья');assert.equal(r(f).factions[0].leaderId,'player');assert.equal(r(f).memberships.player[0].title,'избранный представитель');assert.equal(r(f).factions[0].election.votes,2);});
cap(322,()=>{const f=factionFixture(),one=r(f).factions[0],two=r(f).factions[1];one.relations[two.id]=-2;two.relations[one.id]=-2;one.reputation.player=2;two.reputation.player=2;f.pass('Мирю враждующие группы Мастера Торговцы');assert.equal(r(f).factions[0].relations[two.id],0);assert.equal(r(f).factions[1].relations[one.id],0);assert.ok(r(f).agreements.some(a=>a.type==='treaty'));});
cap(323,()=>{const f=friendFixture();f.local('Илья');f.actor('Ника').hidden=true;f.actor('Ника').status='missing';f.pass('Организую коллективные поиски Ника Мира Илья');const plan=r(f).plans.at(-1);assert.equal(plan.participants.length,2);wait(f,120);assert.equal(f.actor('Ника').hidden,false);assert.equal(r(f).plans.at(-1).status,'completed');});
cap(324,()=>{const f=guildFixture();const street=f.m.world.locations.find(l=>l.name==='улица'),shop=f.m.world.player.location;for(const edge of f.m.world.edges.filter(e=>e.to===street.id&&e.from===shop))edge.rpg={minimumRank:1,factionId:r(f).factions[0].id};f.run('Выхожу');assert.equal(f.last.results[0].code,'access_condition_failed');r(f).memberships.player[0].rank=1;f.pass('Проверяю статусный доступ улица');f.pass('Выхожу');assert.equal(f.m.world.player.location,street.id);});
cap(325,()=>{const f=fixture();f.m.world.player.money=10;inventory(f,'доска');inventory(f,'кирпич');inventory(f,'молоток',{functions:['hammer']});f.pass('Строю инфраструктуру доска и кирпич');f.pass('Принимаю решение для поселения: расширить общественный сад');wait(f,120);f.pass('Принимаю решение для поселения: открыть школу ремесла');wait(f,120);assert.equal(r(f).settlement.decisions.filter(d=>d.status==='completed').length,2);assert.equal(r(f).settlement.prosperity,2);assert.equal(f.m.world.player.money,4);f.save();assert.equal(f.m.world.locations.find(l=>l.id===f.m.world.player.location).environment.development,2);});
test('all 325 numbered capabilities have an executable state-based scenario',()=>{assert.deepEqual([...registered].sort((a,b)=>a-b),Array.from({length:325},(_,i)=>i+1));if(process.env.WRITE_CAPABILITY_FIXTURES==='1'&&!scenarioFailed)writeFileSync(new URL('./action-catalog-fixtures.json',import.meta.url),JSON.stringify(globalThis.ActionCatalog.entries.map(e=>({id:e.id,description:e.description,test:'test/actions325.test.js',scenarios:traces[e.id]})),null,2)+'\n');});
